from lib import *
S = SS('e13')
steps = [
    step("ANS 的思想:用一个整数状态 x 存放已经编码的符号;编码符号 s 就把 x 变大约 1/概率 倍。例:符号 a、b、c 频率 3、3、2(M = 8),编码 abcabcaa,从后往前、初始 x = 16:每步 x' = (x // f) × 8 + (x % f) + 累积频率。a(f=3)让 x 变大约 2.56–2.67 倍,对应 -log2(3/8) = 1.42 位(log2 约 1.36–1.42);c(f=2)让 x 变大约 4 倍,对应 2 位。8 个符号后 x = 87026(17 位)。解码时看 x % 8 落在哪个区间就知道符号,再按反向公式还原,8 步后回到初始的 16。", t=tl(S(1)), done=lidx(S(1), '最终 x = 87026'), mark=lidx(S(1), '编码 "c"(f=2,累积=6):x = 3058'), b=bars([['a 变大倍数', 2.67, '2.67×'], ['c 变大倍数', 4.00, '4.00×'], ['最终 x 的位数', 17, '17 位']], 18, done=[2], mark=[0, 1]), kv=KV([['编码', "x' = (x // f) × M + (x % f) + 累积频率"], ['频率低的符号', 'x 变大得多(c:约 4 倍)'], ['解码', '8 步还原成初始 x = 16']], ['编码'])),
    step("rANS 编码(12 位频率精度,32 位状态,每次输出 16 位)对比 Huffman 和熵,每份 256 KiB。0.5/0.5:熵 32768 字节,Huffman 32768,rANS 32772;0.9/0.1:熵 15407,Huffman 32768(多 112.7%),rANS 15410(多 0.02%);0.99/0.01:熵 2612,Huffman 32768,rANS 2616(多 0.15%);0.999/0.001:熵 346,rANS 350(多 1.14%);16 个符号均匀:rANS 131074,熵 131071;products 文本:熵 168116,Huffman 168967(多 0.5%),rANS 168122(多 0.00%)。所有数据的编码解码往返一致。rANS 在偏斜分布上几乎贴着熵,Huffman 浪费的是“每个符号至少一位”。", t=tl(S(2)), done=lidx(S(2), '0.99 / 0.01'), mark=lidx(S(2), '0.9 / 0.1'), b=bars([['0.9/0.1 熵', 15407, '15407'], ['0.9/0.1 Huffman', 32768, '32768'], ['0.9/0.1 rANS', 15410, '15410'], ['0.99/0.01 rANS', 2616, '2616']], 33000, mark=[1], done=[0, 2, 3]), kv=KV([['0.9/0.1', 'Huffman 多 112.7%,rANS 多 0.02%'], ['0.99/0.01', 'rANS 2616 字节,熵 2612'], ['products 文本', 'Huffman 多 0.5%,rANS 多 0.00%']], ['0.9/0.1'])),
    step("频率的量化精度(表大小 M = 2^k)影响压缩率:0.99/0.01,M=2^6 是 2744,2^8 是 2698,2^10 起是 2694(熵 2690);0.999/0.001,M=2^6 是 952,2^8 是 460,2^10 是 402,2^12 起 390(熵 387);20 个指数衰减符号,M=2^6 是 74860,2^12 是 65518,2^14 是 65470(熵 65457);products 文本,M=2^6 是 189202,2^8 是 168786,2^12 是 168122(熵 168116)。精度太低,小概率被舍入成别的值,偏斜越大越敏感;12 位左右基本够用。", t=tl(S(3)), done=lidx(S(3), 'products 文本'), mark=lidx(S(3), '0.999 / 0.001'), b=bars([['0.999/0.001:M=2^6', 952, '952'], ['M=2^8', 460, '460'], ['M=2^10', 402, '402'], ['M=2^12', 390, '390']], 960, mark=[0], done=[3]), kv=KV([['M = 2^6', '0.999/0.001 多出 146%(952 对 387)'], ['M = 2^12', '390 字节,接近熵 387'], ['products 文本', 'M=2^6 189202,2^12 168122']], ['M = 2^6'])),
    step("tANS(FSE 的做法)把 rANS 的状态转移预先算成一张表,编码解码只查表、移位和读位,不做除法。我按 FSE 的方式把符号散布进大小为 2^R 的表,全部往返一致。0.9/0.1(64 KiB):熵 3878,Huffman 8192,rANS 3882,tANS R=6 是 3883,R=8 起 3880;0.99/0.01:熵 672,Huffman 8192,tANS R=6 695,R=10 起 674;指数衰减 20 符号:熵 16375,tANS R=6 18020,R=8 16701,R=12 16385;products 文本:熵 41972,Huffman 42189,tANS R=6 47301,R=10 41978,R=12 41973。表大小 R 小时精度不够,R 到 10–12 就贴着熵。", t=tl(S(4)), done=lidx(S(4), 'products 文本(64 KiB)'), mark=lidx(S(4), '0.99 / 0.01'), b=bars([['products 熵', 41972, '41972'], ['products Huffman', 42189, '42189'], ['products tANS R=6', 47301, '47301'], ['products tANS R=12', 41973, '41973']], 47500, done=[0, 3], mark=[2]), kv=KV([['tANS R=12', '几乎等于熵(41973 对 41972)'], ['tANS R=6', '47301,表太小精度差'], ['速度来源', '查表、移位,不做除法']], ['tANS R=12'])),
    step("一张具体的 FSE 解码表(R = 4,表大小 16,符号 a、b、c 频率 7、5、4,散布步长 (16>>1)+(16>>3)+3 = 13,表中符号序列 aabcabcabcabcaab):每个状态有符号、要读的位数、新状态基数。符号 a 的 7 个状态里有 1 个读 2 位、6 个读 1 位,各状态读位数平均 1.143 位,而 -log2(7/16) = 1.193 位;b 的 5 个状态平均 1.600 位(-log2 = 1.678);c 的 4 个状态都读 2 位(2.000)。Huffman 给 a/b/c 的码长是 1/2/2 位,整数位;FSE 通过不同的状态读不同的位数,平均出“分数位”。", t=tl(S(5)), done=lidx(S(5), '符号 a:频率'), mark=lidx(S(5), '    状态   符号'), b=bars([['a 平均读位数', 1.143, '1.143'], ['a 的 -log2 概率', 1.193, '1.193'], ['b 平均读位数', 1.600, '1.600'], ['b 的 -log2 概率', 1.678, '1.678']], 1.8, done=[0, 2], mark=[1, 3]), kv=KV([['a(7/16)', '状态读 1 位或 2 位,平均 1.143 位'], ['b(5/16)', '平均 1.600 位'], ['Huffman', 'a/b/c = 1/2/2 位(整数位)']], ['a(7/16)'])),
    step("同一份 LZ77 token(第 11 篇的懒匹配,128 KiB products,14994 个 token,字面量/长度符号 14995 个、字母表 82 种,距离符号 9643 个、字母表 30 种,额外位 14004 字节),熵编码换成 tANS:字面量/长度流熵 9724、Huffman 9768、tANS 9731 字节;距离流熵 4425、Huffman 4463、tANS 4432;合计含额外位 Huffman 28234、tANS 28166 字节,只小 0.2%。作为对照 zlib 级别 9 实际 28019,zstd-19 实际 24762 字节(比 zlib 小 11.6%)。在这份数据上,ANS 对 Huffman 的优势很小;zstd 比 gzip 小的主要原因在别处。", t=tl(S(6)), done=lidx(S(6), '合计(含额外位'), mark=lidx(S(6), 'token 流:'), b=bars([['Huffman 合计', 28234, '28234'], ['tANS 合计', 28166, '28166'], ['zlib 级别 9', 28019, '28019'], ['zstd-19', 24762, '24762']], 28500, mark=[0, 2], done=[3]), kv=KV([['tANS 对 Huffman', '28166 对 28234,小 0.2%'], ['zstd-19 对 zlib-9', '24762 对 28019,小 11.6%'], ['结论', 'ANS 本身贡献很小,差距在别处']], ['结论'])),
]
A = mkarte('e13', 13, '压缩原理,ANS,FSE,rANS,tANS,Huffman,zstd,熵编码,Python,真实验证,动画演示',
    '自己写 rANS 和 tANS(FSE 风格)并往返验证:偏斜分布 0.9/0.1 下 Huffman 比熵多 112.7%、rANS 只多 0.02%;表大小 2^10–2^12 就贴着熵;但对 LZ77 的 token 流,换成 ANS 只比 Huffman 小 0.2%,zstd-19 比 zlib-9 小 11.6% 的主要原因在别处。',
    'zstd 的熵编码用 FSE(一种 ANS)取代了 Huffman。ANS 到底是什么,为什么能做到“分数位”,实际能省多少?这篇自己写出 rANS 和表驱动的 tANS,用真实数据量一量,也诚实地看一下它在 LZ77 token 流上的收益有多小。',
    [('112.7% 对 0.02%', '0.9/0.1 分布下 Huffman 与 rANS 比熵多出的比例'), ('0.2%', '同一份 LZ77 token 流,tANS 比 Huffman 小的比例(28166 对 28234 字节)'), ('11.6%', 'zstd-19 比 zlib-9 小的比例(24762 对 28019 字节),差距主要来自别处')],
    [('状态里存符号', '<p>ANS 用一个整数状态保存已经编码的符号:编码符号 s,状态乘以约 1/概率;解码看状态模 M 落在哪个区间,得到符号再还原。符号越罕见,状态涨得越多,所花的位数就是该符号的 -log2 概率,可以是分数位。</p>'),
     ('接近熵', '<p>rANS 在 0.9/0.1 的分布上只比熵多 0.02%(Huffman 多 112.7%),在 products 文本上几乎等于熵(多 0.00%)。偏斜越大、符号越少,Huffman 浪费越多。</p>'),
     ('量化精度', '<p>频率要缩放到总和为 2^k。k 太小,小概率被舍入,0.999/0.001 的信源在 2^6 时是 952 字节(熵 387),2^12 是 390。12 位左右基本够用。</p>'),
     ('tANS 与 FSE', '<p>tANS 把状态转移预先算成表:每个状态给出符号、要读的位数和新状态基数。解码只查表、读位,没有除法。表大小 2^10–2^12 就贴着熵;太小(R=6)会有明显损失。FSE 是 zstd 采用的 tANS 实现,我按它的符号散布方式(步长 (L>>1)+(L>>3)+3,按记忆写出,表能铺满且往返一致)实现。</p>'),
     ('分数位', '<p>Huffman 给 a/b/c(频率 7/5/4)的码长是 1/2/2 位;FSE 表里 a 的 7 个状态有 6 个读 1 位、1 个读 2 位,平均 1.143 位,更接近 -log2(7/16) = 1.193。</p>'),
     ('实际收益', '<p>对 LZ77 的 token 流(82 种字面量/长度符号加 30 种距离符号),tANS 只比 Huffman 小 0.2%。zstd-19 比 zlib-9 小 11.6%,主要应该来自别的地方(更大的窗口、更好的匹配选择、对“重复使用的距离”的特殊处理等,见第 14、16 篇),这一点我没有逐项拆开验证。ANS 的优势是在符号分布很偏、或者要极快解码的时候。</p>')],
    steps,
    [ENV_E + '。rANS(32 位状态、16 位输出、频率精度可调)和 tANS(表驱动、符号散布方式按 FSE 的做法)都是我手写的 Python 实现,所有编码结果都经过解码往返验证;FSE 的散布步长公式是我按记忆写的,没有对照 zstd 源码;LZ77 token 沿用第 11 篇;zstd 的实际压缩用 zstandard 库;所有数字都是确定性的',
     '没有验证:zstd 内部实际用的 FSE 表格式(归一化频率的存储方式、低概率符号的特殊处理);zstd 的字面量用的是 Huffman 还是 FSE(我没有解析 zstd 帧);zstd 比 gzip 小的各项原因各占多少;ANS 的解码速度(纯 Python 没有意义);交错多路状态(提高并行度)的做法'],
    'ANS 与 FSE')
